package com.mamtrex.hospital.audit; import org.springframework.stereotype.Service; import org.springframework.security.core.context.SecurityContextHolder; @Service public class AuditService { private final AuditEventRepository repo; public AuditService(AuditEventRepository r){repo=r;} public void record(String action,String type,String id,String details){var a=SecurityContextHolder.getContext().getAuthentication(); String actor=a==null?"system":a.getName(); repo.save(new AuditEvent(actor,action,type,id,details));} }
